'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isPositiveZero = require( '@stdlib/math/base/assert/is-positive-zero' );


// MAIN //

/**
* Returns an accumulator function that computes a cumulative maximum while ignoring NaN values.
*
* @returns {Function} accumulator function
*
* @example
* var accumulator = nanmmax();
*/
function nanmmax() {
	var max = null;

	return accumulator;

	/**
	* If called without arguments, returns the current cumulative maximum.
	* Otherwise, updates the cumulative maximum.
	*
	* @private
	* @param {number} [x] - input value
	* @returns {(number|null)} current cumulative maximum (or null if no non-NaN value seen yet)
	*/
	function accumulator( x ) {
		if ( arguments.length === 0 ) {
			return max;
		}

		if ( isnan( x ) ) {
			return max;
		}

		if ( max === null ) {
			max = x;
			return max;
		}

		if (
			x > max ||
			( x === max && isPositiveZero( x ) )
		) {
			max = x;
		}

		return max;
	}
}


// EXPORTS //

module.exports = nanmmax;
